head.script:
scwin.onpageload = function() {

};



	scwin.checkScriptTagsForType = function() {
		const scriptTags = document.querySelectorAll('head script');
		let scriptsWithType = [];
		let revalue = false;

		scriptTags.forEach(function(script) {
			if (script.hasAttribute('type')) {
				scriptsWithType.push(script);
			}else{
				revalue = true;
			}
		});
		return revalue;
	}


	scwin.checkVal1 = function() {
		return scwin.checkScriptTagsForType();
	}	
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_3_column3_filter').getAttribute('value') !== null;
	}			
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('mf_wq_uuid_4_form').getAttribute('target').indexOf('data-') != -1;
	}			
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");			

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
